exec('set_log log_to_file=on')
-- IP ADDRESSES FOR WTS NODES

local SERVER_IP="10.0.2.1"
local DAEMON_IP="10.0.2.1"
local GNB_NG_ADDR="10.0.11.10"
local GNB_XN_ADDR="10.0.12.10"
local PROXY_SERVER_IP="10.0.2.80"
local AMF_NG_ADDR="10.0.11.1"
local UEC_ADDR="72.22.0.1"
local UPF_ADDR="10.12.2.1"

local ENB1_S1_ADDR="10.0.1.136"
local GNB_S1U_ADDR="10.0.1.210"

local ENB1_X2_ADDR="10.0.1.137"
local GNB_X2_ADDR="10.0.1.10"

local MME1_S1_ADDR="10.0.1.131"

local SERVER_ADDR="10.0.1.132"
local SGW_S1U_ADDR="10.0.1.133"
local SGW_S11_ADDR="10.0.1.134"

local ENB_X2U_ADDR="10.0.1.135"
local GNB_X2U_ADDR="10.0.1.210"

local GNB3_NG_ADDR="10.0.11.100"
local GNB3_XN_ADDR="10.0.12.100"
local GNB3_S1U_ADDR="10.0.1.11"
local GNB3_X2_ADDR="10.0.1.11"

local PROXY_SERVER_3_IP="10.0.2.90"

local GNB4_NG_ADDR="10.0.11.101"
local GNB4_XN_ADDR="10.0.12.101"
local PROXY_SERVER_4_IP="10.0.2.91"

local PGW_ADDR="4.7.254.207"

local DAEMON_PORT="10000"


NUMBER_OF_UES_SA=10
NUMBER_OF_UES_NSA=10

-- LTE CONFIG
exec('set_enb id=1 plmn=311:489 s1='..ENB1_S1_ADDR..' enb_id_macro=0x12346 daemon='..SERVER_IP..':'..DAEMON_PORT..' x2='..ENB1_X2_ADDR..' x2u='..ENB_X2U_ADDR..' type=simulated x2_peers=all')
exec('enb_param id=1 drb_id_begin=3 endc_capable_qci=9')
exec('set_cell id=1 enb=1 eci=0x1234601 pci=3:2 tac=222 proxy='..SERVER_IP..':12219|'..SERVER_IP..':8889 earfcn=2000:20000 mapped_earfcn=4200:22200 mandatory_for_activation=off')
exec('enb_endc_param id=1 control_flow_period=3gpp1 use_nr_ran_cont=on')

-- NR CORE CONFIG
exec('set_amf_region id=1 tac_list=7627107,280,788,200 plmn=311:489')
exec('set_amf id=1 daemon='..SERVER_IP..':'..DAEMON_PORT..' ng='..AMF_NG_ADDR..':38412 region=1 set_id=2 pointer=2')
exec('amf_param id=1 full_nas_auth=on nia=null nea=null')
exec('set_upf id=1 daemon='..SERVER_IP..':'..DAEMON_PORT..' type=simulated addr='..UPF_ADDR..'/24 ngu='..AMF_NG_ADDR..' ngu_snd_buff_size=8M ngu_rcv_buff_size=8M ngu_read_packets_threshold=10')

-- EXT GNB AND ITS CELLS
exec('set_gnb id=2 type=external plmn=311:489 ng='..GNB_NG_ADDR..' gnb_id=0x01:22  daemon='..SERVER_IP..':'..DAEMON_PORT..' x2='..GNB_X2_ADDR..':36422 x2_peers=none xn='..GNB_XN_ADDR..' amf=1 s1u='..GNB_S1U_ADDR..'  x2u='..GNB_X2U_ADDR..' nssai=0x1:0xd143a5')
exec('set_cell id=1 gnb=2 pci=16:2 tac=280 nrci=0x01 tdd_cell=on proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nr_arfcn=636666:636666 mandatory_for_activation=off gscn=7880')
exec('set_cell id=2 gnb=2 pci=17:0 tac=280 nrci=0x02 tdd_cell=on proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nr_arfcn=636666:636666 mandatory_for_activation=off gscn=7880')
exec('set_cell id=3 gnb=2 pci=17:1 tac=280 nrci=0x03 tdd_cell=on proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nr_arfcn=636666:636666 mandatory_for_activation=off gscn=7880')
exec('set_cell id=4 gnb=2 pci=17:2 tac=280 nrci=0x04 tdd_cell=on proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nr_arfcn=636666:636666 mandatory_for_activation=off gscn=7880')

-- 4G CORE CONFIG
exec('mme_pool_area id=1 mmegi=1 plmn=311:489 tac_list=777,111,222,444,333,4580')
exec('set_mme id=1 ip='..DAEMON_IP..':'..DAEMON_PORT..' s1='..MME1_S1_ADDR..':36412 supported_rat=lte,nblte pool=1:1')
exec('set_sgw id=1 ip='..DAEMON_IP..':'..DAEMON_PORT..' s1u='..SGW_S1U_ADDR..' s11='..SGW_S11_ADDR..':60100 s5u_snd_buff_size=20971520 s5u_rcv_buff_size=20971520 s1u_snd_buff_size=20971520 s1u_rcv_buff_size=20971520 gtpu_read_packets_threshold=0')
exec('set_pgw id=1 type=simulated ip='..DAEMON_IP..':'..DAEMON_PORT..' addr='..PGW_ADDR..'/16 apn=lteapn1.com.mnc69.mcc450.gprs devtype=tun devname=tunLTEA13 sgi_rcv_buff_size=20971520 sgi_snd_buff_size=20971520 s5u_rcv_buff_size=20971520 s5u_snd_buff_size=20971520 gtpu_read_packets_threshold=0')

-- SIM GNB CONFIG
exec('set_gnb id=3 xn='..GNB3_XN_ADDR..' ng='..GNB3_NG_ADDR..' plmn=311:489 gnb_id=0x02:22 type=simulated daemon='..SERVER_IP..':'..DAEMON_PORT..' nssai=0x01:0xD143A5')
exec('cell_set id=1 gnb=3 tac=200 pci=18:0 nr_arfcn=633000:633000 proxy='..PROXY_SERVER_3_IP..':5555 nrci=0x1 tdd_cell=on gscn=7842 nr_scs=30kHz bs_channel_bandwidth=100MHz meas_timing_carrier_freq=632928 ssb_subcarrier_spacing=kHz30 ssb_mtc_periodicity_and_offset=sf5:0 ssb_mtc_duration=sf1')
exec('gnb_cell_param id=1 gnb=3 enable_anr=on')
exec('gnb_param id=3 sib1_period=40 send_xn_setup=false xn_listening_socket=on measEvent=A5')
exec('gnb_param id=3 sib1_period=200')


-- UE CONFIGURATION
exec('set_uec id=1 ip='..DAEMON_IP..':'..DAEMON_PORT..' peer='..DAEMON_IP..':2152 gtpu=off retries=unlimited  proxy_snd_buf_size=20971520 proxy_rcv_buf_size=20971520 proxy_read_packets_threshold=0')
--

for ue_id=1,NUMBER_OF_UES_SA do
    local ue_id_aligned
    if (ue_id>0 and ue_id<10) then ue_id_aligned = '0'..ue_id
    elseif (ue_id>=10 and ue_id<100) then ue_id_aligned = ue_id
    end
    print(ue_id_aligned)

    exec('set_ue simulated id='..ue_id..
         ' uec=1 release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF00 opc_key=0ED47545168EAFE2C39C075829A7B61F'..
         ' nia=null+zuc nea=null+zuc suci=0:311:489:0000:0:0:0216454'..ue_id_aligned..
        ' mode=nr enb=2 cell=1')
    exec('ue_param id='..ue_id..
         ' ue_nr_')
    exec('set_pdu_gateway id='..ue_id..' ue_nat_ip=72.23.'..ue_id..'.1 dl_nat_gw='..SERVER_IP..' ul_nat_gw='..SERVER_IP)
end

for ue_id=NUMBER_OF_UES_SA+1,NUMBER_OF_UES_NSA+NUMBER_OF_UES_SA do
    local imsi_prefix = '311:489:216455'
    local ue_id_aligned
                if (ue_id>0 and ue_id<10) then ue_id_aligned = '0'..ue_id
                elseif (ue_id>=10 and ue_id<100) then ue_id_aligned = ue_id
                end
                local imsi = imsi_prefix..ue_id_aligned

    exec('set_ue simulated id='..ue_id..
         ' uec=1 release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF00'..
         ' nia=aes+zuc+snow3g+null nea=aes+zuc+snow3g+null'..
         ' imsi='..imsi)
    exec('ue_param id='..ue_id..
         ' ue_nr_'..
         ' dual_conn=eutra_nr'..
         ' ue_eutra_nr_')
    exec('ue_enb_param id='..ue_id..' drx_config=off measurement_gap=gp0:0 gap_trigger=gnb_triggered mgta=ms0 gap_purpose=perUE')

    exec('set_bearer id=2 ue='..ue_id..
         ' qci=9 pdn=1 ip=4.7.254.2'..ue_id..' default=on ul_nat_gw=10.0.2.1 dl_nat_gw=10.0.2.1 trf_type=internal')
end

-- NETWORK SLICING AND QI
exec('set_qosflow id=1 5qi=6 default=on')
exec('set_qosflow id=2 5qi=5')
exec('set_qosflow id=3 5qi=1')
exec('set_qosrule id=1 proto=tcp qos_flow=2')
exec('set_qosrule id=2 proto=udp qos_flow=3')
exec('nwslice_set id=1 qos_flows=1,2,3 qos_rules=1,2 snssai=0x01:0xD143A5 default=on ue=all amf=1')
exec('uec_param id=1 reordering_window_size=1000 reordering_timer=200')

-- MISC
exec('debug_log level=4')
exec('sim_debug_log level=4 mme=1')
exec('sim_debug_log level=1 uec=1')
exec('sim_debug_log level=4 pgw=1')
exec('sim_debug_log level=4 sgw=1')
exec('link_ctrl_param use_hb=off')
exec('trace uec=1 protocol=rrc on')
exec('trace uec=1 protocol=nr_rrc on')
exec('sim_trace uec=1 protocol=nr_rrc on')
exec('sim_trace amf=1 protocol=ng on')
exec('sim_trace uec=1 protocol=all on')
exec('sim_trace amf=1 protocol=all on')
exec('cfg_end')
exec('set_log log_to_file=on')

